        for _, l in ipairs(o.lines or {}) do
            local d = F.designFor(l)
            if d then want[d] = (want[d] or 0) + (l.q or 1) F.hot[d] = os.clock() end
        end
    end
    local keep = val("pr_keep", 3)
    for id, d in pairs(p.designs or {}) do
        if not d.retired and F.hot[id] and os.clock() - F.hot[id] < 600 then want[id] = math.max(want[id] or 0, keep) end
    end
    local best, gap
    for id, n in pairs(want) do
        local g = n - F.stockOf(id)
        if g > 0 and (not gap or g > gap) then best, gap = id, g end
    end
    return best, gap
end
function F.stockCarry()
    local shelves = M.owned("shelf")
    for i = #shelves, 1, -1 do
        M.near(shelves[i])
        local r = inv("StockShelf", shelves[i])
        if r.ok then return true end
    end
    S.gerr = "Shelves full"
    return false
end
function F.produce()
    if next(M.profile().carry or {}) then return F.stockCarry() end
    local machines = M.owned("machine")
    local mid = machines[1] or "printer"
    local p = M.profile()
    local mach = p.machines and p.machines[mid] or {}
    if mach.out then
        M.near(mid)
        local r = inv("CollectOutput", mid)
        if r.ok then
            S.printed += r.count or 0
            F.stockCarry()
        end
        return r.ok
    end
    local d, gap = F.wanted()
    if not d then return false end
    local q = math.max(1, math.min(F.batch, gap))
    M.near(mid)
    local h = inv("HoldPrint", mid, d, q)
    if not h.ok then
        local mx = tonumber(tostring(h.err):match("to (%d+)"))
        if mx then F.batch = mx q = math.min(q, mx) h = inv("HoldPrint", mid, d, q) end
        if h.ok == false and type(h.room) == "number" and h.room > 0 then q = math.min(q, h.room) h = inv("HoldPrint", mid, d, q) end
    end
    if not h.ok and tostring(h.err):lower():find("crate") then F.stockCarry() return true end
    if not h.ok and tostring(h.err):lower():find("collect") then
        local r = inv("CollectOutput", mid)
        if r.ok then S.printed += r.count or 0 F.stockCarry() end
        return true
    end
    if not h.ok then S.gerr = h.err return false end
    local s = inv("StartProduction", mid, d, q)
    if not s.ok then S.gerr = s.err return false end
    S.task = __T["Printing "] .. q
    local t = os.clock()
    while RUNNING and os.clock() - t < 40 do
        task.wait(0.8)
        local r = inv("CollectOutput", mid)
        if r.ok then
            S.printed += r.count or q
            F.stockCarry()
            return true
        end
    end
    return false
end
function F.supplies()
    if not M.items().goodiesShelf then return end
    local p = M.profile()
    local keep = val("su_keep", 10)
    local lvl = M.level()
    for id, t in pairs(D.Brand and D.Brand.touchById or {}) do
        if not t.pass and not t.pack and not t.crate then
            local okU = true
            if D.GR.isTouchUnlocked then local ok, r = pcall(D.GR.isTouchUnlocked, id, M.items()) okU = (not ok) or r ~= false end
            local have = tonumber((p.supplies or {})[id]) or 0
            if okU and have < math.max(1, math.ceil(keep / 2)) then
                local price = D.GR.getGoodiePrice and tonumber(gcall(D.GR.getGoodiePrice, id, lvl)) or math.huge
                local n = keep - have
                local reserve = val("su_reserve", 0)
                while n > 0 and price * n > M.money() - reserve do n -= 1 end
                if n > 0 then
                    M.near("goodiesShelf")
                    local r = inv("BuyGoodies", "goodiesShelf", id, n)
                    if r.ok then S.bought += n LOG("supplies", id, n) end
                end
            end
        end
    end
end
