local P = {}
function P.buy()
    local lvl, items, areas, money = M.level(), M.items(), M.profile().areas or {}, M.money()
    local reserve = val("bu_reserve", 0)
    P.saving = nil
    if on("bu_areas") then
        for _, a in ipairs(D.Areas.areas) do
            if not areas[a.id] and lvl >= (a.level or 1) then
                local prevOk = true
                for i, b in ipairs(D.Areas.areas) do if b.id == a.id and i > 1 and not areas[D.Areas.areas[i - 1].id] then prevOk = false end end
                if prevOk then P.saving = a reserve = math.max(reserve, a.price or 0) break end
            end
        end
        for _, a in ipairs(D.Areas.areas) do
            local ok, can = pcall(D.GR.canBuyArea, a.id, lvl, areas, items, money)
            if ok and can and money - (a.price or 0) >= val("bu_reserve", 0) then
                local r = inv("BuyArea", a.id)
                if r.ok then say(__T["Unlocked "] .. tostring(a.name)) return true end
            end
        end
    end
    local list = {}
    local needForRoom = P.saving ~= nil
    if needForRoom then reserve = val("bu_reserve", 0) end
    for _, it in ipairs(D.Areas.items) do
        if not items[it.id] and not it.starter and not it.exclusive and areas[it.area] then
            local wantKind = needForRoom or (it.kind == "worker" and on("bu_workers")) or (it.kind == "decor" and on("bu_decor")) or (it.kind ~= "worker" and it.kind ~= "decor" and on("bu_items"))
            if wantKind then list[#list + 1] = it end
        end
    end
    table.sort(list, function(a, b) return (a.price or 0) < (b.price or 0) end)
    for _, it in ipairs(list) do
        local ok, can = pcall(D.GR.canBuyItem, it.id, lvl, items, areas, money)
        if ok and can and money - (it.price or 0) >= reserve then
            local r = inv("BuyItem", it.id)
            if r.ok then say(__T["Bought "] .. tostring(it.name)) S.bought += 1 return true end
        end
    end
end
function P.workers()
    local p = M.profile()
    for _, it in ipairs(D.Areas.items) do
        if it.kind == "worker" and (p.items or {})[it.id] then
            local isOn = D.SS and D.SS.isWorkerOn and gcall(D.SS.isWorkerOn, it.id)
            if isOn == false then inv("SetWorkerEnabled", it.id, true) say(tostring(it.name) .. __T[" back to work"]) end
        end
    end
end
