    ThemeManager:SetFolder("COMBO_WICK_MSB")
    SaveManager:SetFolder("COMBO_WICK_MSB")
    ThemeManager:ApplyToTab(Tab)
    pcall(function()
        if not (isfile and isfile("COMBO_WICK_MSB/themes/default.txt")) then ThemeManager:ApplyTheme("Tokyo Night") end
    end)
    SaveManager:BuildConfigSection(Tab)
end)
onClean(function() pcall(function() Library:Unload() end) end)
pcall(function()
    do
        local name, ok, err = SaveManager:GetAutoloadConfig()
        local loaded = false
        if ok and not err then
            loaded = SaveManager:Load(name) == true
            if not loaded then SaveManager.Library:Notify("Autoload config not found, using last settings") end
        end
        if not loaded and isfile and isfile("COMBO_WICK_MSB/settings/auto.json") then SaveManager:Load("auto") end
    end
end)
do
    local pending = false
    local function queue()
        if pending or not RUNNING then return end
        pending = true
        task.delay(1.5, function() pending = false; if RUNNING then pcall(function() if not SaveManager.Library.Unloaded then SaveManager:Save("auto") end end) end end)
    end
    local function skip(k) k = tostring(k); return k == "MenuKeybind" or k:find("^ThemeManager") or k:find("^SaveManager") or k:find("Color") or k == "FeedbackMsg" or k == "FeedbackType" end
    task.delay(2, function()
        for k, t in pairs(Toggles) do if not skip(k) then pcall(function() local prev = t.Changed t:OnChanged(function(...) if prev then pcall(prev, ...) end queue() end) end) end end
        for k, o in pairs(Opt) do if not skip(k) then pcall(function() local prev = o.Changed o:OnChanged(function(...) if prev then pcall(prev, ...) end queue() end) end) end end
    end)
end
function UI.center()
    pcall(function()
        local sg = Library.ScreenGui
        local m = sg and sg:FindFirstChild("Main")
        if not m then return end
        m.AnchorPoint = Vector2.zero
        for _ = 1, 3 do
            local vs, sz, cur = sg.AbsoluteSize, m.AbsoluteSize, m.AbsolutePosition
            local tx, ty = math.max(0, math.floor((vs.X - sz.X) / 2)), math.max(0, math.floor((vs.Y - sz.Y) / 2))
            local k = (m.Size.X.Offset > 0 and sz.X / m.Size.X.Offset) or 1
            if math.abs(cur.X - tx) < 2 and math.abs(cur.Y - ty) < 2 then break end
            m.Position = UDim2.new(m.Position.X.Scale, m.Position.X.Offset + (tx - cur.X) / k, m.Position.Y.Scale, m.Position.Y.Offset + (ty - cur.Y) / k)
            RunService.Heartbeat:Wait()
        end
    end)
end
for _, d in ipairs({ 1, 3, 6 }) do task.delay(d, UI.center) end
setText(UI.exec, __T["Checking your executor..."])
task.spawn(function()
    local miss, dead, core = {}, {}, false
    for _, n in ipairs(getgenv().CW_NEEDS or {}) do if not CAP.cap(n) then miss[#miss + 1] = n end end
    local ps = lp:FindFirstChild("PlayerScripts")
    local function find(n) local m = ps and ps:FindFirstChild(n, true) return m end
    local list = {
        { m = find("ClientData"), core = true },
        { m = find("PlotClient"), core = true },
        { m = find("ShopState"), txt = __T["Keep Workers On and New Rooms don't work on your executor."] },
    }
    for _, e in ipairs(list) do
        local ok, live = pcall(M.liveModule, e.m)
        if ok and live == false then
            if e.core then core = true else dead[#dead + 1] = e.txt end
        end
    end
    if core then dead = { __T["Most features don't work on your executor."] } end
    local lines, msg = {}, nil
    if #miss > 0 then
        msg = __T["Missing:"] .. " " .. table.concat(miss, ", ")
        lines[#lines + 1] = '<font color="#ff6b6b">' .. msg .. '</font>'
    end
    if #dead > 0 then
        msg = dead[1] .. " " .. __T["Use Potassium or Wave."]
        lines[#lines + 1] = '<font color="#f5c542">' .. table.concat(dead, "\n") .. " " .. __T["Use Potassium or Wave."] .. '</font>'
    end
    if #lines == 0 then lines[1] = '<font color="#7ED957">' .. __T["Executor check: all features supported"] .. '</font>' end
    setText(UI.exec, table.concat(lines, "\n"))
    LOG("exec check", "missing=" .. table.concat(miss, ","), "dead=" .. #dead, "core=" .. tostring(core))
    if msg then notify(msg) end
end)
notify(__T["Loaded"])

end
